		axis := report.Axes[key]
		fmt.Fprintf(cmd.OutOrStdout(), "%s: %s", key, axis.State)
		if axis.Detail != "" {
			fmt.Fprintf(cmd.OutOrStdout(), " (%s)", axis.Detail)
		}
		fmt.Fprintln(cmd.OutOrStdout())
	}
